 * @param num_attributes The number of attributes in the result set.
 * @param datetime The timestamp of the query result.
 */
void convert_result_to_format(char* result, const char* source, int num_rows, const char** attributes, int num_attributes, const char* datetime) {
    // Buffer size calculation for safe buffer overflow prevention
    size_t buffer_size = snprintf(NULL, 0, "Query: SELECT * FROM %s | Rows: %d | Columns: ", source, num_rows) + 1;

    // Allocate buffer size for safe buffer overflow prevention
    result = realloc(result, buffer_size);

    // Append buffer size calculation result to buffer for safe buffer overflow prevention
    buffer_size = snprintf(result, buffer_size, "Query: SELECT * FROM %s | Rows: %d | Columns: ", source, num_rows);

    // Append all attributes to buffer separated by comma and a space
    for (int i = 0; i < num_attributes; i++) {
        buffer_size += snprintf(result + buffer_size - 1, buffer_size - buffer_size + 1, "%s%s", attributes[i], i < num_attributes - 1? ", " : "");
    }

    buffer_size += snprintf(result + buffer_size - 1, buffer_size - buffer_size + 1, " | Timestamp: %s\n", datetime);

    // Null terminate buffer for safety
    result[buffer_size - 1] = '\0';
}
