 * @param numRows Number of rows returned by the query.
 * @param fieldNames Array of field names in the query result.
 * @param numFields Number of fields in the query result.
 * @param queryTime Timestamp when the query was executed.
 */
void transform_query_output(char* resultBuffer, const char* dataTable, int numRows, const char** fieldNames, int numFields, const char* queryTime) {
    // Buffer size must be large enough to hold the formatted output
    #define BUFFER_SIZE 1024

    // Check buffer size and truncate buffer if necessary
    if (snprintf(resultBuffer, BUFFER_SIZE, "") < 0) {
        // Buffer size is too small, return error message
        snprintf(resultBuffer, BUFFER_SIZE, "Error: Buffer overflow");
        return;
    }

    // Format the buffer with the query information
    snprintf(resultBuffer, BUFFER_SIZE, "Query: SELECT * FROM %s | Rows: %d | Fields: ", dataTable, numRows);

    // Add field names to the buffer, separated by commas
    for (int i = 0; i < numFields; i++) {
        if (snprintf(resultBuffer + strlen(resultBuffer), BUFFER_SIZE - strlen(resultBuffer), "%s", fieldNames[i]) < 0) {
            // Buffer size is too small, return error message
            snprintf(resultBuffer, BUFFER_SIZE, "Error: Buffer overflow");
            return;
        }
        if (i < numFields - 1) {
            snprintf(resultBuffer + strlen(resultBuffer), BUFFER_SIZE - strlen(resultBuffer), ", ");
        }
    }

    // Add the query execution time to the buffer
    snprintf(resultBuffer + strlen(resultBuffer), BUFFER_SIZE - strlen(resultBuffer), " | Executed At: %s", queryTime);
}
