/**
 * Generate a GLSL variable declaration string for a uniform variable.
 *
 * This function constructs a GLSL variable declaration string in the format:
 *   "uniform vec3 [identifier] = vec3([a], [b], [c]);"
 *
 * It uses the snprintf function for safe buffer overflow protection and variable argument list support.
 *
 * @param result_str Buffer to store the generated GLSL variable declaration.
 * @param identifier The name of the variable.
 * @param... Variable values to be inserted into the GLSL variable declaration.
 */
void generate_shader_variable(char* result_str, const char* identifier,...) {
    va_list args;
    va_start(args, identifier);

    // Buffer size for snprint buffer safety
    size_t buffer_size = 256;
    char buffer[buffer_size];

    snprintf(buffer, buffer_size, "uniform vec3 %s = vec3(", identifier);

    // Append variable values to the buffer
    buffer[snprintf(buffer + strlen(buffer), buffer_size - strlen(buffer), "%.2f", va_arg(args, double)) + 1] = ',';
    buffer[snprintf(buffer + strlen(buffer), buffer_size - strlen(buffer), "%.2f", va_arg(args, double)) + 1] = ',';
    buffer[snprintf(buffer + strlen(buffer), buffer_size - strlen(buffer), "%.2f", va_arg(args, double)) + 1] = ')';

    buffer[snprintf(buffer + strlen(buffer), buffer_size - strlen(buffer), ");\0") - 1] = 0;

    // Copy buffer contents to result buffer safely to avoid buffer overflow
    snprintf(result_str, buffer_size - 1, buffer);

    va_end(args);
